using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DoubleEffectsCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/DoubleEffectsCustomDescription", order = 0)]
public class DoubleEffectsCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		DoubleEffectsAction doubleEffectsAction = battleAction as DoubleEffectsAction;
		string text = "";
		string text2 = "";
		if (doubleEffectsAction.PlayerTarget)
		{
			text = "DoubleEffectOnPlayer";
			text2 = "PlayerSelfEffect";
		}
		else if (doubleEffectsAction.EnemyTarget)
		{
			text = "DoubleEffectOnEnemy";
			text2 = "ThatEnemyEffect";
		}
		else
		{
			text = "DoubleEffectOnTarget";
			text2 = "ThatTargetEffect";
		}
		string localizedString = base.localizationManager.GetLocalizedString(text);
		string format = base.localizationManager.GetLocalizedString(text2).LowercaseFirst();
		string effectName = doubleEffectsAction.NothingToDoubleEffectAction.Effect.GetEffectName();
		format = Smart.Format(format, doubleEffectsAction.NothingToDoubleEffectActionAmount, effectName);
		return Smart.Format(localizedString, effectName, format) + (doubleEffectsAction.Fortify ? ("\n" + Smart.Format(GetRawLocalizedDescription(doubleEffectsAction), GetAmountWithoutEquation(amountModified))) : "");
	}
}
